//! Signature verification tests.
//!
//! Every vector below is either generated by a real signing key in the test or
//! taken from a published specification. The negative cases matter most: a
//! verifier that accepts malformed input is worse than no verifier.

use crate::signature::{
    decode_hex, evm_address_from_public_key, keccak256, verify_auto, verify_eip191_message,
    verify_ed25519, verify_secp256k1_digest, SignatureAlgorithm,
};

use ed25519_dalek::{Signer, SigningKey};
use k256::ecdsa::signature::hazmat::PrehashSigner;
use k256::ecdsa::{RecoveryId, Signature as K256Signature, SigningKey as K256SigningKey};


/// Build a deterministic secp256k1 key from a fixed seed.
fn secp_key(seed: u8) -> K256SigningKey {
    let mut bytes = [0u8; 32];
    for (i, b) in bytes.iter_mut().enumerate() {
        *b = seed.wrapping_add(i as u8).wrapping_mul(7).max(1);
    }
    K256SigningKey::from_slice(&bytes).expect("valid scalar")
}

#[test]
fn secp256k1_digest_signature_verifies() {
    let key = secp_key(3);
    let digest = keccak256(b"tigerwallet transfer authorization");
    let signature: K256Signature = key.sign_prehash(&digest).expect("sign");
    let public_key = key.verifying_key().to_encoded_point(false).as_bytes().to_vec();

    let result = verify_secp256k1_digest(&digest, &signature.to_bytes(), None, &public_key);
    assert!(result.valid, "a genuine signature must verify: {:?}", result.reason);
    assert_eq!(result.algorithm, SignatureAlgorithm::Secp256k1);
    assert!(result.signer.starts_with("0x"));
    assert_eq!(result.signer.len(), 42);
}

#[test]
fn secp256k1_rejects_a_different_digest() {
    let key = secp_key(5);
    let digest = keccak256(b"original payload");
    let signature: K256Signature = key.sign_prehash(&digest).expect("sign");
    let public_key = key.verifying_key().to_encoded_point(false).as_bytes().to_vec();

    let tampered = keccak256(b"tampered payload");
    let result = verify_secp256k1_digest(&tampered, &signature.to_bytes(), None, &public_key);
    assert!(!result.valid, "a signature must not verify over a different digest");
}

#[test]
fn secp256k1_rejects_a_different_key() {
    let signer = secp_key(9);
    let other = secp_key(11);
    let digest = keccak256(b"authorization");
    let signature: K256Signature = signer.sign_prehash(&digest).expect("sign");
    let other_public = other.verifying_key().to_encoded_point(false).as_bytes().to_vec();

    let result = verify_secp256k1_digest(&digest, &signature.to_bytes(), None, &other_public);
    assert!(!result.valid, "a signature must not verify against an unrelated key");
}

#[test]
fn secp256k1_rejects_malformed_input() {
    let key = secp_key(13);
    let digest = keccak256(b"payload");
    let public_key = key.verifying_key().to_encoded_point(false).as_bytes().to_vec();

    // Wrong signature length.
    assert!(!verify_secp256k1_digest(&digest, &[0u8; 63], None, &public_key).valid);
    // Wrong digest length.
    assert!(!verify_secp256k1_digest(&[0u8; 31], &[0u8; 64], None, &public_key).valid);
    // Empty key.
    assert!(!verify_secp256k1_digest(&digest, &[0u8; 64], None, &[]).valid);
    // All-zero signature is not a valid (r, s) pair.
    assert!(!verify_secp256k1_digest(&digest, &[0u8; 64], None, &public_key).valid);
}

#[test]
fn secp256k1_recovery_id_must_match_the_key() {
    let key = secp_key(17);
    let digest = keccak256(b"recoverable authorization");
    let (signature, recovery_id): (K256Signature, RecoveryId) =
        key.sign_prehash_recoverable(&digest).expect("sign");
    let public_key = key.verifying_key().to_encoded_point(false).as_bytes().to_vec();

    let correct = verify_secp256k1_digest(&digest, &signature.to_bytes(), Some(recovery_id.to_byte()), &public_key);
    assert!(correct.valid, "the matching recovery id must verify: {:?}", correct.reason);

    // The opposite parity recovers a different key.
    let wrong_id = recovery_id.to_byte() ^ 1;
    let wrong = verify_secp256k1_digest(&digest, &signature.to_bytes(), Some(wrong_id), &public_key);
    assert!(!wrong.valid, "a mismatched recovery id must be rejected");
}

#[test]
fn eip191_personal_sign_round_trips() {
    let key = secp_key(19);
    let message = b"Sign in to TigerWallet";

    let prefix = format!("\x19Ethereum Signed Message:\n{}", message.len());
    let mut hasher = sha3::Keccak256::new();
    use sha3::Digest;
    hasher.update(prefix.as_bytes());
    hasher.update(message);
    let digest: [u8; 32] = hasher.finalize().into();

    let signature: K256Signature = key.sign_prehash(&digest).expect("sign");
    let public_key = key.verifying_key().to_encoded_point(false).as_bytes().to_vec();

    let result = verify_eip191_message(message, &signature.to_bytes(), &public_key);
    assert!(result.valid, "EIP-191 message must verify: {:?}", result.reason);

    // A different message must not verify.
    let other = verify_eip191_message(b"Sign in to Attacker", &signature.to_bytes(), &public_key);
    assert!(!other.valid, "EIP-191 verification must bind to the exact message");
}

#[test]
fn evm_address_is_derived_from_the_public_key() {
    let key = secp_key(23);
    let public_key = key.verifying_key().to_encoded_point(false).as_bytes().to_vec();
    let address = evm_address_from_public_key(&public_key).expect("address");

    assert_eq!(address.len(), 42);
    assert!(address.starts_with("0x"));

    // The same key always yields the same address.
    assert_eq!(address, evm_address_from_public_key(&public_key).unwrap());

    // A different key yields a different address.
    let other = secp_key(29);
    let other_public = other.verifying_key().to_encoded_point(false).as_bytes().to_vec();
    assert_ne!(address, evm_address_from_public_key(&other_public).unwrap());
}

#[test]
fn ed25519_signature_verifies() {
    let signing_key = SigningKey::from_bytes(&[7u8; 32]);
    let message = b"solana transaction payload";
    let signature = signing_key.sign(message);
    let public_key = signing_key.verifying_key().to_bytes();

    let result = verify_ed25519(message, &signature.to_bytes(), &public_key);
    assert!(result.valid, "a genuine Ed25519 signature must verify: {:?}", result.reason);
    assert_eq!(result.algorithm, SignatureAlgorithm::Ed25519);
}

#[test]
fn ed25519_rejects_tampered_input() {
    let signing_key = SigningKey::from_bytes(&[9u8; 32]);
    let message = b"cosmos send";
    let signature = signing_key.sign(message);
    let public_key = signing_key.verifying_key().to_bytes();

    assert!(!verify_ed25519(b"cosmos send modified", &signature.to_bytes(), &public_key).valid);
    assert!(!verify_ed25519(message, &[0u8; 64], &public_key).valid);
    assert!(!verify_ed25519(message, &signature.to_bytes(), &[0u8; 31]).valid);
}

#[test]
fn verify_auto_selects_the_algorithm_from_key_length() {
    // Ed25519 key: 32 bytes.
    let signing_key = SigningKey::from_bytes(&[11u8; 32]);
    let message = b"auto dispatch";
    let signature = signing_key.sign(message);
    let ed = verify_auto(message, &signature.to_bytes(), &signing_key.verifying_key().to_bytes());
    assert!(ed.valid);
    assert_eq!(ed.algorithm, SignatureAlgorithm::Ed25519);

    // secp256k1 key: 65 bytes uncompressed.
    let key = secp_key(31);
    let digest = keccak256(message);
    let sig: K256Signature = key.sign_prehash(&digest).expect("sign");
    let public_key = key.verifying_key().to_encoded_point(false).as_bytes().to_vec();
    let secp = verify_auto(message, &sig.to_bytes(), &public_key);
    assert!(secp.valid);
    assert_eq!(secp.algorithm, SignatureAlgorithm::Secp256k1);

    // An unsupported key length is reported as unknown, never as valid.
    let unknown = verify_auto(message, &sig.to_bytes(), &[1u8; 17]);
    assert!(!unknown.valid);
    assert_eq!(unknown.algorithm, SignatureAlgorithm::Unknown);
}

#[test]
fn decode_hex_handles_prefixes_and_rejects_bad_input() {
    assert_eq!(decode_hex("0xdeadbeef").unwrap(), vec![0xde, 0xad, 0xbe, 0xef]);
    assert_eq!(decode_hex("DEADBEEF").unwrap(), vec![0xde, 0xad, 0xbe, 0xef]);
    assert!(decode_hex("").is_err());
    assert!(decode_hex("0x").is_err());
    assert!(decode_hex("abc").is_err(), "odd-length hex must be rejected");
    assert!(decode_hex("zz").is_err(), "non-hex characters must be rejected");
}

#[test]
fn keccak256_matches_the_published_empty_hash() {
    // keccak256("") is a well-known constant.
    let expected = "c5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470";
    assert_eq!(hex::encode(keccak256(b"")), expected);
}
